/** Every branch supplies a distinct observed condition, cause and two concrete checks.
 * Three yes/no questions are deliberate triage, not proof of causality.
 * No generic numerical parameter patch is derived from these guides.
 */
function guide(id: string, label: string, category: DefectCategory, description: string, aliases: string[], source: keyof typeof sources, branches: readonly [Branch, Branch, Branch]): DefectGuide {
  return {
    id, label, category, description, aliases, source: sources[source],
    questions: branches.map(([key, question]) => ({ id: key, label: question, options: [{ value: 'yes', label: 'Sì' }, { value: 'no', label: 'No' }, { value: 'unknown', label: 'Non verificato' }] })),
    causes: branches.map(([key, , title, explanation, target, check, trial]) => ({ id: `${id}-${key}`, title, explanation, target, evidence: [{ question: key, values: ['yes'] }], checks: [check, trial] })),
  }
}

